# frozen_string_literal: true

require 'rails_helper'

# Migrated from features/studies/study_report.feature
#
# Study reports are a spreadsheet summarising the QC state of a study. They are generated by a delayed job.
describe 'Study reports' do
  let(:manager) { create(:user, login: 'user', roles: [create(:role, name: 'manager')]) }
  let(:admin) { create(:admin, login: 'admin') }
  let!(:study_a) { create(:study, name: 'Study A') }
  let!(:study_b) { create(:study, name: 'Study B') }
  let(:plate_barcode) { 'SQPD-1234567' }
  let(:report_time) { Time.zone.parse('Mon Jul 12 10:23:58 UTC 2010') }

  # A row of the study reports table. Reports that are still being generated have nothing to download or rerun.
  def report_row(study_name, state)
    if state == :completed
      [study_name, '2010-07-12', 'user', 'Download', 'Rerun']
    else
      [study_name, '2010-07-12', 'user', 'Processing', '']
    end
  end

  def expect_reports_table(*rows)
    expect(fetch_table('table#study_list')).to eq([['Study', 'Created on', 'Created by', 'Download', 'Rerun'], *rows])
  end

  # A stock plate with three wells, each containing a sample, that are part of the study.
  def create_stock_plate_for(study)
    stock_purpose = create(:stock_plate_purpose, name: 'Stock Plate')
    plate = create(:plate, barcode: plate_barcode, plate_purpose: stock_purpose, well_count: 3, well_order: :row_order)
    plate.wells.each_with_index do |well, index|
      well.aliquots.create!(sample: create(:sample, name: "Sample_#{plate_barcode}_#{index + 1}"))
      well.well_attribute.update!(
        gender_markers: %w[F F F F],
        sequenom_count: 29,
        concentration: 1,
        pico_pass: 'Pass',
        gel_pass: 'Pass',
        measured_volume: 500.0
      )
    end
    RequestFactory.create_assets_requests(plate.wells, study)
  end

  # The values expected in the report for one well of the stock plate, in the order of the columns checked above.
  def stock_plate_report_row(sample_number, well)
    [
      'Study B',
      plate_barcode,
      '1.0',
      '29/30',
      'FFFF',
      'Pass',
      'Pass',
      "Sample_#{plate_barcode}_#{sample_number}",
      well,
      '0.5',
      '500.0'
    ]
  end

  def work_off_delayed_jobs
    Delayed::Worker.new(quiet: true).work_off(Delayed::Job.count)

    expect(Delayed::Job.where.not(last_error: nil).pluck(:last_error)).to be_empty
    expect(Delayed::Job.count).to eq(0)
  end

  def generate_study_report_for(study)
    StudyReport.create!(study:).tap(&:perform)
  end

  # Picks the named columns out of a CSV, as the report has many more columns than the ones we care about.
  def csv_columns(csv_text, columns)
    CSV.parse(csv_text, headers: true).map { |row| columns.map { |column| row[column] } }
  end

  def last_report_columns_for(study, columns)
    csv_columns(study.study_reports.last.report.file.read, columns)
  end

  context 'when logged in as a manager' do
    before do
      login_user(manager)
      travel_to(report_time)
    end

    it 'lists the reports for a given study' do
      create(:pending_study_report, study: study_a, user: manager)
      create(:completed_study_report, study: study_a, user: manager)

      visit study_information_path(study_a)
      click_link 'Study QC Reports'

      expect(page).to have_text('QC Reports for Study A')
      expect_reports_table(report_row('Study A', :completed), report_row('Study A', :pending))
    end

    it 'lists the reports for a given user' do
      create(:pending_study_report, study: study_a, user: manager)
      create(:completed_study_report, study: study_b, user: manager)

      visit profile_path(manager)
      expect(page).to have_current_path(profile_path(manager))
      expect(page).to have_text('Qc Reports')

      click_link 'Qc Reports'

      expect(page).to have_text('Qc Reports for user')
      expect_reports_table(report_row('Study B', :completed), report_row('Study A', :pending))
    end

    it 'filters the reports by a given study' do
      create(:pending_study_report, study: study_a, user: manager)
      create(:completed_study_report, study: study_b, user: manager)

      visit study_reports_path
      expect_reports_table(report_row('Study B', :completed), report_row('Study A', :pending))

      click_link 'Study A'

      expect_reports_table(report_row('Study A', :pending))
    end

    it 'lists all the reports' do
      create(:pending_study_report, study: study_a, user: manager)
      create(:completed_study_report, study: study_b, user: manager)

      visit study_reports_path

      expect_reports_table(report_row('Study B', :completed), report_row('Study A', :pending))
    end

    it 'generates a new report from the study reports homepage' do
      create_stock_plate_for(study_b)

      visit study_reports_path
      expect(page).to have_text('New report for')
      select 'Study B', from: 'Study'
      click_button 'Submit'

      expect(page).to have_text('Report being generated')
      expect_reports_table(report_row('Study B', :pending))
      expect(Delayed::Job.last.priority).to eq(100)

      work_off_delayed_jobs
      visit study_reports_path
      expect_reports_table(report_row('Study B', :completed))

      click_link 'Download report for Study B'

      columns = [
        'Study',
        'Plate',
        'Concentration',
        'Sequenome Count',
        'Sequenome Gender',
        'Pico',
        'Gel',
        'Supplier Sample Name',
        'Well',
        'Total Micrograms',
        'Initial Volume'
      ]
      expect(csv_columns(page.source, columns)).to eq(
        [
          stock_plate_report_row(1, 'A1'),
          stock_plate_report_row(2, 'A2'),
          stock_plate_report_row(3, 'A3')
        ]
      )
    end
  end

  context 'when logged in as an administrator' do
    before do
      login_user(admin)
      travel_to(report_time)
    end

    it 'shows the report job on the delayed jobs page until it has been processed' do
      create_stock_plate_for(study_b)

      visit study_reports_path
      expect(page).to have_text('New report for')
      select 'Study B', from: 'Study'
      click_button 'Submit'
      expect(page).to have_text('Report being generated')

      visit admin_delayed_jobs_path
      expect(page).to have_text('generate study report')

      work_off_delayed_jobs
      visit admin_delayed_jobs_path

      expect(page).to have_current_path(admin_delayed_jobs_path)
      expect(page).to have_no_text('generate study report')
    end
  end

  context 'when a report is generated' do
    before { create_stock_plate_for(study_b) }

    it 'has one row per well when the wells have child sample tubes' do
      Well.find_each { |well| well.children << create(:sample_tube) }
      RequestFactory.create_assets_requests(SampleTube.all, study_b)
      generate_study_report_for(study_b)

      expect(last_report_columns_for(study_b, %w[Study Plate Well])).to eq(
        [['Study B', 'SQPD-1234567', 'A1'],
         ['Study B', 'SQPD-1234567', 'A2'], ['Study B', 'SQPD-1234567', 'A3']]
      )
    end

    it 'shows the samples as awaiting a manifest when no manifest has been uploaded' do
      generate_study_report_for(study_b)

      expect(last_report_columns_for(study_b, %w[Study Plate Well Status])).to eq(
        [
          ['Study B', 'SQPD-1234567', 'A1',
           'Awaiting manifest'],
          ['Study B', 'SQPD-1234567', 'A2',
           'Awaiting manifest'],
          ['Study B', 'SQPD-1234567', 'A3',
           'Awaiting manifest']
        ]
      )
    end

    it 'shows the samples as updated by manifest when a sample manifest has updated them' do
      Sample.find_each { |sample| sample.update!(updated_by_manifest: true) }
      generate_study_report_for(study_b)

      expect(last_report_columns_for(study_b, %w[Study Plate Well Status])).to eq(
        [
          ['Study B', 'SQPD-1234567', 'A1',
           'Updated by manifest'],
          ['Study B', 'SQPD-1234567', 'A2',
           'Updated by manifest'],
          ['Study B', 'SQPD-1234567', 'A3',
           'Updated by manifest']
        ]
      )
    end
  end
end
